DROP PROCEDURE IF EXISTS check_book_stock;
DELIMITER //
CREATE PROCEDURE check_book_stock()
BEGIN
  DECLARE done BOOLEAN DEFAULT FALSE;
  DECLARE v_category VARCHAR(30);
  DECLARE v_count INT;
  DECLARE cur CURSOR FOR SELECT b_category,b_count FROM books;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO v_category,v_count;
    IF done THEN LEAVE read_loop; END IF;
    IF v_count<3 THEN
      SELECT CONCAT(v_category,'此图书需要补充库存！') AS message;
    END IF;
  END LOOP;
  CLOSE cur;
END //
DELIMITER ;
CALL check_book_stock();

DROP PROCEDURE IF EXISTS check_unreturned;
DELIMITER //
CREATE PROCEDURE check_unreturned()
BEGIN
  DECLARE done BOOLEAN DEFAULT FALSE;
  DECLARE v_category VARCHAR(30);
  DECLARE cur CURSOR FOR SELECT i.b_category FROM borrow b JOIN borrow_items i ON i.borrow_id=b.borrow_id WHERE b.borrow_state='进行中' AND b.returned_at IS NULL;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO v_category;
    IF done THEN LEAVE read_loop; END IF;
    SELECT CONCAT(v_category,'此图书需要归还！') AS message;
  END LOOP;
  CLOSE cur;
END //
DELIMITER ;
CALL check_unreturned();

DROP PROCEDURE IF EXISTS check_due_soon;
DELIMITER //
CREATE PROCEDURE check_due_soon()
BEGIN
  DECLARE done BOOLEAN DEFAULT FALSE;
  DECLARE v_category VARCHAR(30);
  DECLARE cur CURSOR FOR SELECT i.b_category FROM borrow b JOIN borrow_items i ON i.borrow_id=b.borrow_id WHERE b.borrow_state='进行中' AND b.returned_at IS NULL AND b.due_at>NOW() AND b.due_at<NOW()+INTERVAL 1 DAY;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO v_category;
    IF done THEN LEAVE read_loop; END IF;
    SELECT CONCAT(v_category,'此图书距离归还不到1天！') AS message;
  END LOOP;
  CLOSE cur;
END //
DELIMITER ;
CALL check_due_soon();

DROP PROCEDURE IF EXISTS check_material_stock;
DELIMITER //
CREATE PROCEDURE check_material_stock()
BEGIN
  DECLARE done BOOLEAN DEFAULT FALSE;
  DECLARE v_name VARCHAR(60);
  DECLARE v_count INT;
  DECLARE cur CURSOR FOR SELECT m_name,m_put_count FROM materials;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO v_name,v_count;
    IF done THEN LEAVE read_loop; END IF;
    IF v_count<=2 THEN
      SELECT CONCAT(v_name,'需要补充库存！') AS message;
    END IF;
  END LOOP;
  CLOSE cur;
END //
DELIMITER ;
CALL check_material_stock();

DROP PROCEDURE IF EXISTS project_material_count;
DELIMITER //
CREATE PROCEDURE project_material_count(IN p_project_name VARCHAR(60))
BEGIN
  DECLARE v_count INT;
  IF EXISTS(SELECT 1 FROM projects WHERE p_name=p_project_name) THEN
    SELECT COUNT(DISTINCT pr.pr_m_number) INTO v_count
    FROM projects p LEFT JOIN provides pr ON pr.pr_p_number=p.p_number
    WHERE p.p_name=p_project_name;
    SELECT CONCAT(p_project_name,'项目共需要',v_count,'种原材料') AS message;
  ELSE
    SELECT CONCAT(p_project_name,'项目还没有记录') AS message;
  END IF;
END //
DELIMITER ;
CALL project_material_count('南京甲');

DROP FUNCTION IF EXISTS project_material_info;
DELIMITER //
CREATE FUNCTION project_material_info(p_project_name VARCHAR(60),p_material_name VARCHAR(60))
RETURNS JSON READS SQL DATA
BEGIN
  DECLARE v_result JSON;
  SELECT JSON_ARRAYAGG(JSON_OBJECT(
    '项目名',p.p_name,'原材料名',m.m_name,
    '原材料单价',m.m_price,'供应商',pr.pr_s_number,'供应数量',pr.pr_count
  )) INTO v_result
  FROM projects p JOIN provides pr ON pr.pr_p_number=p.p_number
  JOIN materials m ON m.m_number=pr.pr_m_number
  WHERE p.p_name=p_project_name AND m.m_name=p_material_name;
  RETURN COALESCE(v_result,JSON_ARRAY());
END //
DELIMITER ;
SELECT project_material_info('南京甲','原材料A');

DROP PROCEDURE IF EXISTS find_suppliers;
DELIMITER //
CREATE PROCEDURE find_suppliers(IN p_keyword VARCHAR(60))
BEGIN
  DECLARE v_count INT;
  SELECT COUNT(DISTINCT s.s_id) INTO v_count
  FROM suppliers s JOIN products p ON p.s_id=s.s_id
  WHERE p.p_name LIKE CONCAT('%',p_keyword,'%');
  IF v_count>0 THEN
    SELECT CONCAT('共找到',v_count,'个供应商提供',p_keyword,'商品!') AS message;
  ELSE
    SELECT CONCAT('没有供应商提供',p_keyword,'商品') AS message;
  END IF;
END //
DELIMITER ;
CALL find_suppliers('手机');

DROP PROCEDURE IF EXISTS show_cart;
DELIMITER //
CREATE PROCEDURE show_cart(IN p_user_id INT)
BEGIN
  SELECT p.p_id,p.p_name,p.price,c.quantity,c.added_at
  FROM cart c JOIN products p ON p.p_id=c.p_id
  WHERE c.u_id=p_user_id
  ORDER BY c.added_at DESC,c.p_id ASC;
END //
DELIMITER ;
CALL show_cart(1);
